from typing import List

class Solution:
    def minMaxSums(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        limit = k - 1
        comb = [0] * (limit + 1)
        comb[0] = 1

        ways = [0] * n
        ways[0] = 1

        for m in range(1, n):
            upto = min(m, limit)
            for r in range(upto, 0, -1):
                comb[r] = (comb[r] + comb[r - 1]) % MOD
            ways[m] = sum(comb[:upto + 1]) % MOD

        ans = 0
        for i, x in enumerate(nums):
            count_as_max = ways[i]
            count_as_min = ways[n - 1 - i]
            ans = (ans + x * (count_as_max + count_as_min)) % MOD

        return ans
